ValidationRule.errorConditionFormula:
AND(
  NOT(ISBLANK(TEXT(Funding_Basis__c))),
  OR(
    AND(
      ISPICKVAL(Funding_Basis__c, "Dollar"),
      OR(ISBLANK(Initial_Funding_Amount__c), NOT(ISBLANK(Initial_Funding_Percentage__c)))
    ),
    AND(
      ISPICKVAL(Funding_Basis__c, "Percent"),
      OR(ISBLANK(Initial_Funding_Percentage__c), NOT(ISBLANK(Initial_Funding_Amount__c)))
    )
  )
)
